'use strict';
const $=id=>document.getElementById(id);
const rates={compact:{min:1700,limit:120,label:'Малогабаритная установка'},standard:{min:null,limit:300,label:'Буровая на грузовом шасси'}};
const money=n=>new Intl.NumberFormat('ru-RU').format(n);
let mode='calc',step=0,quizComplete=false;
const answers={place:'',usage:'',people:'',access:''};
const questions=[{key:'place',title:'Где находится ваш участок?',hint:'Населённого пункта достаточно. Точный адрес пока не нужен.'},{key:'usage',title:'Как планируете пользоваться водой?',options:['Жить в доме круглый год','Приезжать на дачу в сезон','Для строительства','Пока не определился']},{key:'people',title:'Сколько человек будет пользоваться водой?',options:['1–2 человека','3–4 человека','5 и более','Другое / пока не знаю']},{key:'access',title:'Как обстоят дела с заездом техники?',options:['Есть свободный широкий подъезд','Узкие ворота или мало места','Есть другие ограничения','Нужно оценить со специалистом']}];
function getEstimate(){const depth=Number($('depth').value),rate=rates[$('construction').value];return{depth,rate,valid:Number.isInteger(depth)&&depth>=10&&depth<=rate.limit,min:depth*rate.min,max:depth*rate.min};}
function updateCalc(){const e=getEstimate();$('depth-warning').hidden=e.valid;$('depth-warning').textContent=`Укажите целую глубину от 10 до ${e.rate.limit} м для выбранной установки. Возможность работ подтверждает специалист.`;$('estimate').textContent=e.valid&&e.rate.min?`от ${money(e.min)} ₽`:'По запросу';$('formula').textContent=e.valid&&e.rate.min?`${e.depth} м × от ${money(e.rate.min)} ₽/м`:'Специалист уточнит конструкцию и стоимость.';$('extras').replaceChildren();for(const[id,label]of[['pump','Насос и автоматика'],['house','Подводка воды в дом']]){if($(id).checked){const line=document.createElement('div');line.className='extra-line';const text=document.createElement('span');text.textContent=label;const cost=document.createElement('b');cost.textContent='Отдельная смета';line.append(text,cost);$('extras').append(line);}}}
$('depth').addEventListener('input',()=>{$('depth-range').value=$('depth').value;updateCalc();});$('depth-range').addEventListener('input',()=>{$('depth').value=$('depth-range').value;updateCalc();});['construction','pump','house'].forEach(id=>$(id).addEventListener('change',updateCalc));
function setMode(next){mode=next;for(const type of['calc','quiz']){$(`tab-${type}`).setAttribute('aria-selected',String(type===mode));$(`tab-${type}`).tabIndex=type===mode?0:-1;$(`${type}-panel`).hidden=type!==mode;$(`${type}-result-content`).hidden=type!==mode;}$('result-label').textContent=mode==='calc'?'БУРЕНИЕ / ПРИМЕР РАСЧЁТА':'ПОДБОР / ПАРАМЕТРЫ УЧАСТКА';if(mode==='quiz'){renderQuestion();renderQuizSummary();}}
['calc','quiz'].forEach(type=>{$(`tab-${type}`).addEventListener('click',()=>setMode(type));$(`tab-${type}`).addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'calc':e.key==='End'?'quiz':type==='calc'?'quiz':'calc';setMode(next);$(`tab-${next}`).focus();}});});
function startQuiz(){setMode('quiz');$('calculator').scrollIntoView({behavior:'smooth'});}
document.querySelectorAll('[data-start-quiz]').forEach(button=>button.addEventListener('click',startQuiz));
function renderQuestion(){const q=questions[step];$('quiz-step').textContent=`Вопрос ${step+1} из ${questions.length}`;$('progress-fill').style.width=`${(step+1)/questions.length*100}%`;$('quiz-back').hidden=step===0;$('quiz-next').textContent=step===questions.length-1?'Завершить подбор →':'Далее →';$('quiz-error').textContent='';const box=$('quiz-content');box.replaceChildren();const heading=document.createElement('h3');heading.textContent=q.title;box.append(heading);if(q.key==='place'){const label=document.createElement('label');label.className='field';label.textContent='Населённый пункт';const input=document.createElement('input');input.id='quiz-place';input.name='place';input.placeholder='Например, Первоуральск';input.maxLength=120;input.value=answers.place||$('location').value;input.required=true;label.append(input);const hint=document.createElement('p');hint.className='hint';hint.textContent=q.hint;box.append(label,hint);}else{const group=document.createElement('div');group.className='quiz-options';group.setAttribute('role','radiogroup');group.setAttribute('aria-label',q.title);q.options.forEach((option,i)=>{const label=document.createElement('label');label.className='quiz-choice';const input=document.createElement('input');input.type='radio';input.name=q.key;input.value=option;input.checked=answers[q.key]===option;input.required=true;const text=document.createElement('span');text.textContent=option;label.append(input,text);group.append(label);});box.append(group);}}
function saveStep(){const q=questions[step];const value=q.key==='place'?$('quiz-place').value.trim():$('quiz-form').querySelector(`input[name="${q.key}"]:checked`)?.value;if(!value){$('quiz-error').textContent='Выберите ответ, чтобы продолжить.';return false;}answers[q.key]=value;if(q.key==='place')$('location').value=value;renderQuizSummary();return true;}
$('quiz-form').addEventListener('submit',e=>{e.preventDefault();if(!saveStep())return;if(step<questions.length-1){step++;renderQuestion();}else{quizComplete=true;prepareLead();}});$('quiz-back').addEventListener('click',()=>{const q=questions[step];const value=q.key==='place'?$('quiz-place').value.trim():$('quiz-form').querySelector(`input[name="${q.key}"]:checked`)?.value;if(value)answers[q.key]=value;step=Math.max(0,step-1);renderQuestion();});
function renderQuizSummary(){const dl=$('quiz-summary');dl.replaceChildren();for(const[key,label]of[['place','Участок'],['usage','Использование'],['people','Пользователи'],['access','Подъезд']]){if(answers[key]){const dt=document.createElement('dt');dt.textContent=label;const dd=document.createElement('dd');dd.textContent=answers[key];dl.append(dt,dd);}}}
function summary(){if(mode==='quiz')return[['Использование',answers.usage],['Пользователи',answers.people],['Подъезд',answers.access]].filter(row=>row[1]).map(row=>row.join(': ')).join('\n')+'\nГлубину, конструкцию и стоимость нужно уточнить со специалистом.';const e=getEstimate();let s=`Предполагаемая глубина: ${$('depth').value} м\nКонструкция: ${e.rate.label}\n`;s+=e.valid&&e.rate.min?`Пример стоимости бурения: от ${money(e.min)} ₽\nНижний ориентир по опубликованной цене от 1 700 ₽/м. Состав тарифа и актуальность нужно подтвердить.`:'Стоимость: требуется индивидуальное уточнение.';if($('pump').checked)s+='\nДополнительно: насос и автоматика, стоимость уточнить.';if($('house').checked)s+='\nДополнительно: подводка воды в дом, стоимость уточнить.';return s;}
function prepareLead(){if(mode==='quiz'&&!quizComplete){$('quiz-error').textContent='Завершите четыре вопроса или заполните заявку ниже.';$('quiz-panel').scrollIntoView({behavior:'smooth'});return;}$('lead-summary').value=summary();$('request').scrollIntoView({behavior:'smooth'});$('location').focus({preventScroll:true});}
$('prepare-lead').addEventListener('click',prepareLead);document.querySelectorAll('[data-package]').forEach(button=>button.addEventListener('click',()=>{$(button.dataset.package).checked=true;if(button.dataset.package==='house')$('pump').checked=true;setMode('calc');updateCalc();$('calculator').scrollIntoView({behavior:'smooth'});}));
$('lead-form').addEventListener('submit',event=>{event.preventDefault();const digits=$('phone').value.replace(/\D/g,'');if(!/^[78]\d{10}$/.test(digits)){$('form-error').textContent='Введите российский номер: +7 или 8 и ещё 10 цифр.';$('phone').focus();return;}if(!$('location').value.trim()){$('form-error').textContent='Укажите населённый пункт.';$('location').focus();return;}$('form-error').textContent='';const params=$('lead-summary').value.trim()||'Параметры скважины нужно уточнить.';const text=[`Участок: ${$('location').value.trim()}`,$('name').value.trim()?`Имя: ${$('name').value.trim()}`:'',`Телефон: ${$('phone').value.trim()}`,'',params].filter(Boolean).join('\n');$('final-summary').textContent=text;$('copy-status').textContent='';$('lead-dialog').showModal();});$('dialog-close').addEventListener('click',()=>$('lead-dialog').close());$('lead-dialog').addEventListener('click',e=>{if(e.target===$('lead-dialog')){const r=$('lead-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('lead-dialog').close();}});$('copy-lead').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('final-summary').textContent);$('copy-status').textContent='Текст скопирован. Заявка не отправлена.';}catch{$('copy-status').textContent='Не удалось скопировать автоматически. Выделите текст заявки и скопируйте вручную.';}});
function showContact(open){$('contact-panel').hidden=!open;$('contact-toggle').setAttribute('aria-expanded',String(open));} $('contact-toggle').addEventListener('click',()=>showContact($('contact-panel').hidden));$('contact-close').addEventListener('click',()=>showContact(false));$('contact-request').addEventListener('click',()=>showContact(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')showContact(false);});updateCalc();
const photoDialog=document.querySelector('#photo-dialog');
document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{const photo=document.querySelector('#photo-large');photo.src=button.dataset.photo;photo.alt=button.dataset.caption;document.querySelector('#photo-caption').textContent=button.dataset.caption;photoDialog.showModal()}));
document.querySelector('#photo-close').addEventListener('click',()=>photoDialog.close());
photoDialog.addEventListener('click',event=>{if(event.target===photoDialog)photoDialog.close()});
